{"path": "/app/bin/payroll.py", "content": "#!/usr/bin/env python3
"""Payroll summary: python3 payroll.py INPUT_DIR OUTPUT_FILE (rules in docs/payroll-rules.md)."""
import csv
import glob
import gzip
import io
import json
import math
import os
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    t = b.decode("utf-8-sig")
    return t


def text_lines(path):
    t = read_text(path)
    return [ln for ln in t.replace("\r\n", "\n").replace("\r", "\n").split("\n") if ln.strip() != ""]


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d


def to_epoch(d):
    return int(d.astimezone(UTC).timestamp()) if d.microsecond == 0 else math.floor(
        (d - datetime(1970, 1, 1, tzinfo=UTC)).total_seconds())


def epoch_of_dt(d):
    return (d.astimezone(UTC) - datetime(1970, 1, 1, tzinfo=UTC)) // timedelta(seconds=1)


def utc_from_epoch(e):
    return datetime(1970, 1, 1, tzinfo=UTC) + timedelta(seconds=e)


def local_to_epoch(naive, tz, dst=None, first=True):
    """Local wall time -> epoch seconds. dst: True/False to disambiguate repeated times."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset():
        # repeated or skipped time
        cands = [a, b]
        # repeated iff fold=1 has the smaller offset (clocks went back)
        if b.utcoffset() < a.utcoffset():
            if dst is True:
                pick = [c for c in cands if c.dst()]
                pick = pick[0] if pick else a
            elif dst is False:
                pick = [c for c in cands if not c.dst()]
                pick = pick[0] if pick else b
            else:
                pick = a
            return epoch_of_dt(pick)
        return epoch_of_dt(a)
    return epoch_of_dt(a)


def num_floor(v):
    return int(math.floor(Decimal(str(v))))


def norm_dir(s):
    s = str(s).strip().upper()
    if s in ("IN", "I", "K", "CLOCK_IN"):
        return "IN"
    if s in ("OUT", "O", "G", "CLOCK_OUT"):
        return "OUT"
    raise ValueError("bad direction %r" % s)


def std_offset_seconds(tz):
    # standard offset: offset minus dst at a few instants, take the one with dst()==0
    best = None
    for y in (2026, 2025, 2024):
        for m in (1, 4, 7, 10):
            d = datetime(y, m, 15, 12, tzinfo=tz)
            if not d.dst():
                return int(d.utcoffset().total_seconds())
            best = int((d.utcoffset() - d.dst()).total_seconds())
    return best


def split_csv_rows(lines, delimiter, quoting=csv.QUOTE_MINIMAL):
    return list(csv.reader(lines, delimiter=delimiter, quoting=quoting))


# ---------------------------------------------------------------- parsers
# each parser yields (punch_id, employee, direction, epoch, dst_hint) -> returns (id, emp, dir, epoch)

def iter_table(lines, delimiter, is_header, quoting=csv.QUOTE_MINIMAL):
    header = None
    for row in csv.reader(lines, delimiter=delimiter, quoting=quoting):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if is_header(cells):
            header = cells
            continue
        if header is None:
            continue
        yield dict(zip(header, cells))


def parse_abbr(path, tz):
    lines = text_lines(path)
    hdr = lambda c: "Badge" in c and "Punch" in c and "Record" in c
    for r in iter_table(lines, ",", hdr):
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].strip()
        up = t.upper()
        if up.endswith("AM") or up.endswith("PM"):
            body = t[:-2].strip()
            h, m, s = [int(x) for x in body.split(":")]
            h = h % 12
            if up.endswith("PM"):
                h += 12
        else:
            h, m, s = [int(x) for x in t.split(":")]
        naive = d.replace(hour=h, minute=m, second=s)
        z = r.get("Zone", "").strip().upper()
        dst = True if z.endswith("DT") else (False if z.endswith("ST") else None)
        yield r["Record"], r["Badge"], norm_dir(r["Punch"]), local_to_epoch(naive, tz, dst)


def parse_epoch_jsonl(path, tz):
    schema = 1
    for ln in text_lines(path):
        o = json.loads(ln, parse_float=Decimal)
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            if "punch_id" not in o:
                continue
            yield str(o["punch_id"]), o["employee"], norm_dir(o["direction"]), num_floor(o["epoch_ms"]) // 1000 \
                if False else math.floor(Decimal(str(o["epoch_ms"])) / 1000)
        else:
            if "id" not in o:
                continue
            if "ts_ms" in o:
                e = math.floor(Decimal(str(o["ts_ms"])) / 1000)
            else:
                e = num_floor(o["ts"])
            yield str(o["id"]), o["emp"], norm_dir(o["dir"]), e


def parse_offset_csv(path, tz):
    lines = text_lines(path)
    hdr = lambda c: "punch_id" in c and "timestamp" in c
    for r in iter_table(lines, ";", hdr):
        d = parse_iso(r["timestamp"])
        yield r["punch_id"], r["employee"], norm_dir(r["event"]), epoch_of_dt(d)


def parse_legacy(path, tz, site_std):
    offset = site_std
    for ln in text_lines(path):
        c = ln[:1]
        if c == "H":
            extra = ln[13:18].strip()
            if extra and extra[0] in "+-" and len(extra) == 5:
                sign = 1 if extra[0] == "+" else -1
                offset = sign * (int(extra[1:3]) * 3600 + int(extra[3:5]) * 60)
            else:
                offset = site_std
        elif c == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            dr = ln[15:16]
            ts = ln[16:30]
            d = datetime.strptime(ts, "%Y%m%d%H%M%S")
            e = (d - datetime(1970, 1, 1)) // timedelta(seconds=1) - offset
            yield pid, "E" + badge, norm_dir(dr), e


def parse_de_tsv(path, tz):
    lines = text_lines(path)
    hdr = lambda c: "Ausweis" in c and "Buchung" in c
    for r in iter_table(lines, "\t", hdr, quoting=csv.QUOTE_NONE):
        d = datetime.strptime(r["Datum"], "%d.%m.%Y")
        h, m = [int(x) for x in r["Uhrzeit"].split(":")[:2]]
        naive = d.replace(hour=h, minute=m)
        z = r.get("Zeitzone", "").strip().upper()
        dst = True if z == "MESZ" else (False if z == "MEZ" else None)
        yield r["Nr"], r["Ausweis"], norm_dir(r["Buchung"]), local_to_epoch(naive, tz, dst)


def parse_local_csv(path, tz):
    lines = text_lines(path)
    hdr = lambda c: "employee_id" in c and "local_time" in c
    for r in iter_table(lines, ",", hdr):
        naive = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        yield r["punch_ref"], r["employee_id"], norm_dir(r["direction"]), local_to_epoch(naive, tz, None)


def parse_local_jsonl(path, tz):
    for ln in text_lines(path):
        o = json.loads(ln)
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        yield str(p["id"]), p["badge"], norm_dir(p["type"]), local_to_epoch(naive, tz, None)


# ---------------------------------------------------------------- main logic
def read_csv_file(path):
    lines = text_lines(path)
    return [dict((k.strip(), (v or "").strip()) for k, v in r.items() if k is not None)
            for r in csv.DictReader(lines)]


def main(indir, outfile):
    period = json.load(open(os.path.join(indir, "period.json")))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_file(os.path.join(indir, "sites.csv")):
        sites[r["site"]] = (ZoneInfo(r["timezone"]), r["format"])
    employees = {}
    emp_order = []
    for r in read_csv_file(os.path.join(indir, "employees.csv")):
        if r["employee_id"] not in employees:
            emp_order.append(r["employee_id"])
        employees[r["employee_id"]] = r
    rates = {}
    for r in read_csv_file(os.path.join(indir, "rates.csv")):
        rates.setdefault(r["employee_id"], []).append(
            (date.fromisoformat(r["effective_from"]), Decimal(r["hourly_rate"])))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site, id) -> dict(emp, dir, t)
    ever = set()
    for site, (tz, fmt) in sites.items():
        files = sorted(p for p in glob.glob(os.path.join(indir, "exports", site, "**", "*"), recursive=True)
                       if os.path.isfile(p))
        for path in files:
            if fmt == "abbr-csv":
                it = parse_abbr(path, tz)
            elif fmt == "epoch-jsonl":
                it = parse_epoch_jsonl(path, tz)
            elif fmt == "offset-csv":
                it = parse_offset_csv(path, tz)
            elif fmt == "legacy-fixed":
                it = parse_legacy(path, tz, std_offset_seconds(tz))
            elif fmt == "de-tsv":
                it = parse_de_tsv(path, tz)
            elif fmt == "local-csv":
                it = parse_local_csv(path, tz)
            elif fmt == "local-jsonl":
                it = parse_local_jsonl(path, tz)
            else:
                raise ValueError("unknown format " + fmt)
            for pid, emp, dr, e in it:
                key = (site, str(pid).strip())
                if key in punches:
                    continue
                punches[key] = {"emp": str(emp).strip(), "dir": dr, "t": e}
                ever.add(key)

    # 2. corrections
    corr = []
    cdir = os.path.join(indir, "corrections")
    if os.path.isdir(cdir):
        for path in sorted(glob.glob(os.path.join(cdir, "**", "*"), recursive=True)):
            if os.path.isfile(path):
                corr.extend(read_csv_file(path))
    corr = [c for c in corr if c.get("correction_id")]
    corr = [c for c in corr if parse_iso(c["issued_at"]) <= cutoff]
    corr.sort(key=lambda c: (parse_iso(c["issued_at"]), c["correction_id"]))
    voided = set()
    applied = 0
    for c in corr:
        key = (c["site"], c["punch_id"])
        act = c["action"].strip().lower()
        if act == "void":
            if key in punches and key not in voided:
                voided.add(key)
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches and key not in voided:
                punches[key]["t"] = epoch_of_dt(parse_iso(c["time"]))
                applied += 1
        elif act == "add":
            if key not in ever:
                punches[key] = {"emp": c["employee"], "dir": norm_dir(c["type"]),
                                "t": epoch_of_dt(parse_iso(c["time"]))}
                ever.add(key)
                applied += 1

    by_emp = {}
    for (site, pid), p in punches.items():
        if p["emp"] in employees:
            by_emp.setdefault(p["emp"], []).append((p["t"], 0 if p["dir"] == "OUT" else 1, site, pid, p["dir"]))

    def home_tz(emp):
        return sites[employees[emp]["home_site"]][0]

    def round_t(t, tz):
        off = int(tz.fromutc(utc_from_epoch(t)).utcoffset().total_seconds())
        local = t + off
        r = ((local + 180) // 360) * 360
        return t + (r - local)

    def workday(t, tz):
        return tz.fromutc(utc_from_epoch(t)).date()

    exc = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    shifts = {e: [] for e in employees}

    for emp, lst in by_emp.items():
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        htz = home_tz(emp)
        kept = []
        for t, _, site, pid, dr in lst:
            if kept and kept[-1][1] == dr and t - kept[-1][0] <= 300:
                r = round_t(t, sites[site][0])
                if pstart <= workday(r, htz) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            kept.append((t, dr, site, pid))
        # round
        rk = [(round_t(t, sites[site][0]), dr, site) for t, dr, site, pid in kept]
        i = 0
        n = len(rk)
        cur_in = None
        for (r, dr, site) in rk:
            if dr == "IN":
                if cur_in is not None:
                    if pstart <= workday(cur_in[0], htz) <= pend:
                        exc["open_shifts"] += 1
                cur_in = (r, site)
            else:
                if cur_in is not None and r - cur_in[0] <= 16 * 3600:
                    shifts[emp].append((cur_in[0], r, cur_in[1]))
                    cur_in = None
                else:
                    if cur_in is not None:
                        if pstart <= workday(cur_in[0], htz) <= pend:
                            exc["open_shifts"] += 1
                        cur_in = None
                    if pstart <= workday(r, htz) <= pend:
                        exc["orphan_outs"] += 1
        if cur_in is not None and pstart <= workday(cur_in[0], htz) <= pend:
            exc["open_shifts"] += 1

    out_emps = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tot_gross = 0
    for emp in emp_order:
        htz = home_tz(emp)
        lst = sorted(shifts[emp], key=lambda s: s[0])
        lst = [s for s in lst if pstart <= workday(s[0], htz) <= pend]
        day_paid = {}
        week_cnt = {}
        n_sh = paid_sum = ot_sum = night_sum = 0
        pay = Fraction(0)
        for (ti, to, site) in lst:
            wd = workday(ti, htz)
            worked = max(0, (to - ti) // 60)
            paid = worked - 30 if worked > 360 else worked
            # night
            tz = sites[site][0]
            night = 0
            t = ti
            while t < to:
                step = min(60, to - t)
                lh = tz.fromutc(utc_from_epoch(t)).hour
                if step == 60 and (lh >= 22 or lh < 6):
                    night += 1
                elif step < 60:
                    pass
                t += 60
            night = min(night, paid)
            before = day_paid.get(wd, 0)
            day_paid[wd] = before + paid
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            nonot = paid - daily_ot
            wk = wd - timedelta(days=wd.weekday())
            wb = week_cnt.get(wk, 0)
            week_cnt[wk] = wb + nonot
            weekly_ot = max(0, wb + nonot - 2400) - max(0, wb - 2400)
            ot = daily_ot + weekly_ot
            regular = paid - ot
            rl = [r for r in rates.get(emp, []) if r[0] <= wd]
            if rl:
                rate = rl[-1][1]
            elif rates.get(emp):
                rate = rates[emp][0][1]
            else:
                rate = Decimal(0)
            rate = Fraction(rate)
            pay += rate * (Fraction(regular) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            n_sh += 1
            paid_sum += paid
            ot_sum += ot
            night_sum += night
        cents = math.floor(pay * 100 + Fraction(1, 2))
        gross = "%d.%02d" % divmod(cents, 100)
        out_emps[emp] = {"shifts": n_sh, "paid_minutes": paid_sum, "overtime_minutes": ot_sum,
                         "night_minutes": night_sum, "gross": gross}
        tot["shifts"] += n_sh
        tot["paid_minutes"] += paid_sum
        tot["overtime_minutes"] += ot_sum
        tot["night_minutes"] += night_sum
        tot_gross += cents
    tot["gross"] = "%d.%02d" % divmod(tot_gross, 100)

    result = {"period": {"start": period["start"], "end": period["end"]},
              "employees": out_emps, "exceptions": exc, "totals": tot}
    os.makedirs(os.path.dirname(os.path.abspath(outfile)), exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(result, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
"}
